"""Prepare updated academic narrative from the live-verified three-seed snapshot."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
data=json.loads((HERE/'slide_content_v2.json').read_text(encoding='utf-8'))
v=json.loads((HERE/'assets/three_seeds_verified.json').read_text(encoding='utf-8'))
S={s['number']:s for s in data['slides']}
A=v['aggregates'];D=v['paired']
def f(x,d=4):return f'{x:.{d}f}'.replace('.',',')
def ms(method,metric,d=4):return f(A[method][metric]['mean'],d)+' ± '+f(A[method][metric]['sd'],d)
def update(n,title=None,message=None,notes=None,methods=None):
    s=S[n]
    if title:s['title']=title
    if message:s['message']=message
    if notes:s['notes']=notes
    if methods is not None:
        s['seedMethods']=methods
        # Keep supplemental evidence in notes; the footer prioritizes seed runs.
        s['runs']=[name for name in s['runs'] if name not in ['base-training','acil-k5','dac-no-plc-k5','dsal-k5']]

core=['acil-k5','dac-no-plc-k5','dsal-k5']
update(1,notes='Nhóm gồm Lâm Hoàng Vũ – 23122056, Nguyễn Bá Nam – 23122043, Chung Tín Đạt – 23122024. Bộ slide đọc hiểu DS-AL của Zhuang và cộng sự tại AAAI 2024, tái dựng độc lập main ridge, DAC và PLC, rồi đánh giá trên CIFAR-100 B50. E1 và E2 dùng ba seed 0, 1, 2; các khảo sát K và buffer vẫn là seed 0. Mỗi seed có backbone huấn luyện độc lập và projection riêng; trong cùng seed, ba phương pháp dùng chung dữ liệu, checkpoint, class order và feature cache. Số liệu được đọc từ logs, config, checkpoint và các run W&B finished công khai; không sử dụng run thất bại hoặc số liệu tổng hợp giả. Chọn Core scope, không nhận tái hiện toàn bộ ImageNet. Seed 0 từng resume từ CUDA sang CPU tại epoch 19; seed 1 và 2 dùng CPU xuyên suốt. Hạn chế backend này được giữ trong diễn giải thống kê.')
update(7,message='K=5: sáu lần đánh giá trên 50, 60, 70, 80, 90, 100 lớp',
       notes='CIFAR-100 có 50.000 ảnh train và 10.000 ảnh test. B50 nghĩa là huấn luyện backbone trên 50 lớp base; 50 lớp còn lại chia thành K pha mới. K=5 cho thêm 10 lớp mỗi pha; pha 0 là base, vì vậy có sáu điểm accuracy. Trong mỗi pha, chỉ dữ liệu lớp mới dùng để cập nhật các head analytic; đánh giá trên mọi lớp đã gặp. Ba seed 0, 1, 2 thay class order, khởi tạo backbone, minibatch/augmentation và projection. Trong từng seed, ACIL, DAC không PLC và DS-AL dùng cùng feature cache và cùng phép chiếu. Khảo sát K=25/50 giữ seed 0, không gộp các cấu hình K vào mean ba seed. Mỗi lần đánh giá dựa trên tập test cố định tương ứng các lớp đã gặp.',methods=['dsal-k5'])
base=[r for r in v['runs'] if r['method']=='base-training']
update(9,title='Mỗi seed có một backbone độc lập',message='Ba ResNet-32, mỗi backbone học 160 epoch trên 50 lớp base',
       notes='Mỗi seed huấn luyện ResNet-32 từ khởi tạo riêng, SGD với lr=0,1, momentum=0,9, weight decay=0,0005, batch 128; giảm lr tại epoch 80 và 120. Augmentation gồm crop và flip như seed 0. Sử dụng checkpoint epoch 160, không chọn bằng accuracy test. Biểu đồ là accuracy test trên các lớp base của từng seed, không phải accuracy incremental cuối cùng. Accuracy base cuối seed 0/1/2 lần lượt '+', '.join(f(r['history'][-1]['base/test_accuracy'],2)+'%' for r in base)+'. Các seed có class order khác nhau nên tập lớp base khác nhau. Sau huấn luyện, mỗi backbone bị đóng băng và chỉ trích một feature cache dùng chung cho ba biến thể trong cùng seed. Seed 0 resume từ CUDA sang CPU sau epoch 19; seed 1/2 dùng CPU xuyên suốt. Không coi ba lượt là cùng backend từng bit. Checkpoint lưu optimizer, scheduler, RNG và DataLoader để resume đúng trạng thái hợp lệ.',methods=['base-training'])
S[16]['notes']=S[16]['notes'].replace('Benchmark seed 0 dùng stats, float64.','Cả ba seed benchmark dùng stats, float64.')
update(21,title='Trung bình qua pha và qua seed',message='Ā_s gộp sáu pha của một seed; mean ± SD gộp ba seed độc lập',
       notes='Dùng chỉ số s cho seed và k cho pha để tách hai tầng trung bình. Với K=5, A_s,k là accuracy (%) trên mọi lớp đã gặp ở pha k của seed s. A-bar_s = (A_s,0 + … + A_s,5)/6, bao gồm pha base. A_s,5 là accuracy pha cuối trên 100 lớp. Sau đó tính mean của ba A-bar_s để báo cáo A-bar chung; tính riêng mean của ba A_s,5 để báo cáo A_K chung. SD mẫu dùng sqrt(sum((x_s−mean)^2)/(3−1)), n=3 và ddof=1. Không coi 18 điểm pha là 18 lần lặp độc lập. SD mô tả biến thiên giữa seed, không phải standard error hoặc confidence interval. Ví dụ DS-AL: A-bar = '+ms('dsal-k5','average_accuracy')+'%, A_K = '+ms('dsal-k5','last_accuracy')+'%. Ba cột nhỏ biểu diễn A_K của từng seed; công thức tổng hợp không thay đổi cách đánh giá trong từng seed.',methods=['dsal-k5'])
update(22,message='E1 và E2: ba seed; E3 và khảo sát K: seed 0',
       notes='E1 đối sánh ACIL với DS-AL trên CIFAR-100 B50, ResNet-32, K=5, tương ứng phần không trong ngoặc của Table 1. E1 đã hoàn thành seed 0, 1, 2. E2 so ACIL, DAC không PLC và DS-AL đầy đủ trên cùng ba seed để tách tác dụng DAC/PLC trong protocol CIFAR. E2 chuyển từ ImageNet-Full/C=1,4 của Table 2 sang CIFAR-100/C=0,6; vì dataset, backbone và C thay đổi, không nhận tái hiện nguyên Table 2 hoặc khái quát kết quả sang ImageNet. Không có bằng chứng giảng viên đã chấp nhận riêng phạm vi chuyển này; đây là giới hạn học thuật cần nói rõ, không phải điều kiện đã hoàn tất. E3 là phân tích buffer nhóm thiết kế, chỉ seed 0. Khảo sát K=25/50 cũng chỉ seed 0. Ba seed dữ liệu tổng hợp ở phụ lục là bằng chứng cơ chế riêng, không được dùng thay các seed CIFAR thật.')
update(23,message='Ghép cặp trong từng seed; độc lập giữa seed 0, 1 và 2',
       notes='Dataset uoft-cs/cifar100 được pin tại revision aadb3af77e9048adbea6b47c21a81e47dd092ae5, đầy đủ 50.000/10.000 ảnh. Class order dùng NumPy RandomState(s). Mỗi seed có checkpoint ResNet-32 epoch 160 và feature cache riêng, được xác minh SHA-256. Trong một seed, ba phương pháp chia sẻ cùng checkpoint, class order, dữ liệu, augmentation protocol, feature cache và projection seed. Thay đổi giữa seed gồm khởi tạo backbone, thứ tự dữ liệu, augmentation và projection; không chỉ đổi tên run. Giữ m=8192, gamma=0,1, C=0,6, tanh, projection N(0,1) không bias, stats/float64, analytic batch 512. Seed 1/2 dùng torch 2.5.1+cpu; seed 0 có đoạn CUDA rồi CPU. W&B worker dùng SDK 0.23.1 offline, đọc/sync dùng 0.31.0. Bản sửa công cụ sync chỉ đợi/làm mới trạng thái server, không thay mã học thuật hay hyperparameters. Tất cả 12 run thuộc ba seed đã được đối chiếu trực tiếp lại với W&B, config và history.',methods=core)
update(24,message='15 kiểm thử đạt; checkpoint và dữ liệu của ba seed được đối chiếu',
       notes='Nhóm tự triển khai các thành phần học thuật trong src/methods/analytic.py, không sao chép phần đóng góp nghiên cứu từ mã tác giả. Bộ pytest có 15 kiểm thử đạt: ridge tăng lớp bằng nghiệm joint; residual sau nghiệm main cuối pha và PLC đúng cột; chunk size không đổi ngữ nghĩa của triển khai nhóm; disjoint classes; protocol; resume giữ quỹ đạo tối ưu trên cùng backend trong kiểm thử; sync từ bản sao, chặn run ID sai và từ chối history khác; làm mới trạng thái W&B khi server cập nhật chậm; không tính SD nếu chưa đủ ba seed khác nhau. Kiểm tra artifact bổ sung đọc lại checkpoint epoch 160, feature cache và chín classifier: trọng số backbone khác giữa seed; projection giống giữa phương pháp trong một seed và khác giữa seed. Kiểm thử số không chứng minh tái hiện trọn paper hoặc nguyên nhân gap. Mã tác giả chỉ được chạy riêng để đối chiếu ở phụ lục, không dùng tạo số liệu benchmark của nhóm.')
update(25,message='E1/E2 ghép cặp ba seed; K và buffer giữ nguyên seed 0',
       notes='Trong mỗi seed, ACIL, DAC không PLC và DS-AL dùng chung backbone ResNet-32, feature cache, class order và random projection. ACIL tắt compensation; DAC không PLC bật nhánh bù nhưng không làm sạch cột lớp cũ; DS-AL đầy đủ bật DAC và PLC. Mỗi seed mới huấn luyện backbone độc lập đủ 160 epoch. Vì vậy chênh lệch giữa phương pháp được tính theo cặp trong cùng seed rồi trung bình ba cặp. E1/E2 không trộn checkpoint, dữ liệu hoặc cấu hình khác nhau. Khảo sát K=5/25/50 và buffer m=512/1024/2048/8192 giữ kết quả seed 0, không thay hàng K5 hoặc m8192 bằng mean ba seed. Khi thay m, projection cùng seed nhưng không lồng nhau, nên khảo sát buffer vẫn chỉ một realization. E2 là ablation chuyển từ ImageNet-Full sang CIFAR-100, không tái hiện nguyên Table 2.',methods=core)
update(27,title='Paper và nhóm trên ba seed',message='CIFAR-100 B50, K=5; nhóm báo mean ± SD mẫu, n=3',
       notes='Đối sánh theo Table 1 phần CIFAR-100 ResNet-32, không dùng kết quả ResNet-18 trong ngoặc. Paper: ACIL A-bar 66,30%, A_K 57,78%; DS-AL A-bar 66,39%, A_K 58,26%. Nhóm ba seed: ACIL A-bar '+ms('acil-k5','average_accuracy')+'%, A_K '+ms('acil-k5','last_accuracy')+'%; DS-AL A-bar '+ms('dsal-k5','average_accuracy')+'%, A_K '+ms('dsal-k5','last_accuracy')+'%. Thanh paper chỉ thể hiện mean; không gán SD của nhóm cho paper. Thanh nhóm và error bar thể hiện mean và SD mẫu ddof=1 từ ba kết quả, không phải CI. Trục cột bắt đầu từ 0 để không phóng đại gap. Hai phương pháp dùng cùng dữ liệu/biểu diễn trong từng seed; giữa seed, class order và backbone độc lập. Protocol tương ứng phần CIFAR nhưng implementation độc lập, stats solver và backend resume của seed 0 là những giới hạn cần giữ. Mỗi hyperlink seed dẫn đến đúng run tạo số liệu.',methods=['acil-k5','dsal-k5'])
update(28,title='Định lượng sai lệch với paper',message='So mean ba seed với mean paper; tách điểm phần trăm và phần trăm tương đối',
       notes='Chênh lệch tuyệt đối được tính bằng mean nhóm trừ mean paper, đơn vị điểm phần trăm (pp). Chênh lệch tương đối = 100 × (mean nhóm − mean paper)/mean paper. ACIL có gap A-bar −1,1681 pp (−1,7618% tương đối) và A_K −1,4100 pp (−2,4403%). DS-AL có gap A-bar −1,1324 pp (−1,7057%) và A_K −1,4867 pp (−2,5518%). Đây là khoảng cách giữa các mean, không phải chênh của riêng seed 0. SD của nhóm mô tả độ biến thiên ba seed, chưa giải thích nguyên nhân reproduction gap. Không gọi −1,4867 pp là −1,4867% tương đối. Chưa có kiểm định phù hợp, nên không khẳng định gap hoặc cải thiện có ý nghĩa thống kê. Các khả năng như class order, initialization, projection, chi tiết training, cách giải và backend cần thí nghiệm kiểm soát riêng để kết luận nhân quả.',methods=['acil-k5','dsal-k5'])
update(29,message='E2 chuyển sang CIFAR-100, ba seed; không tái hiện nguyên Table 2',
       notes='Bảng báo mean ± SD mẫu ddof=1 của A-bar và A_K trên seed 0, 1, 2. ACIL là baseline không compensation; DAC không PLC bật compensation nhưng không làm sạch residual lớp cũ; DS-AL đầy đủ có DAC và PLC. Mean A_K lần lượt '+', '.join(ms(m,'last_accuracy')+'%' for m in core)+'. Chênh ghép cặp DS-AL−ACIL ở A_K là +0,31/+0,34/+0,56 pp; mean +0,4033 pp, SD của ba chênh +0,1365 pp. PLC so DAC không PLC: +0,63/+0,42/+0,36 pp; mean +0,4700 pp, SD +0,1418 pp. Hai cải thiện đều dương ở 3/3 seed. DAC đơn lẻ so ACIL có A_K −0,32/−0,08/+0,20 pp, mean −0,0667 pp, nên dấu không nhất quán. A-bar tăng trung bình +0,1257 pp cho DS-AL−ACIL và +0,3100 pp cho PLC. SD của chênh ghép cặp được tính từ ba chênh, không cộng SD hai phương pháp. Không kết luận ý nghĩa thống kê từ n=3. E2 chuyển ImageNet-Full/C=1,4 sang CIFAR/C=0,6; không suy luận hiệu quả ImageNet hoặc tự nhận phạm vi đã được giảng viên chấp nhận.',methods=core)
update(30,message='Mỗi đường là mean ba seed; error bar là SD mẫu tại từng pha',
       notes='Với mỗi phương pháp và mỗi pha k, lấy accuracy từ phases.json của seed 0, 1, 2, tính mean và SD mẫu ddof=1. Biểu đồ không gộp các pha thành lần lặp độc lập, không dùng run thất bại. Các đường khác màu, kiểu nét và marker; error bar là ±1 SD giữa seed, không phải CI. Trục accuracy phóng 50–80% và được ghi rõ; vị trí X là số lớp đã gặp 50/60/70/80/90/100. Bảng phải là mean±SD của A_K, không phải số seed 0. Đường trung bình gần nhau và error bar chồng lấn không phải một kiểm định. So DS-AL với ACIL ở pha cuối, mean novel accuracy tăng '+f(D['dsal_minus_acil']['novel_accuracy']['mean'])+' pp, mean base accuracy giảm '+f(D['dsal_minus_acil']['base_accuracy']['mean'])+' pp; cùng hai nhóm test 5.000 ảnh nên lợi ích tổng bằng một nửa tổng hai chênh. Đây là mô tả đánh đổi trong CIFAR, không khẳng định cơ chế nhân quả đã được tách riêng.',methods=core)
update(31,message='Chỉ seed 0: A_K dao động 0,04 pp khi K=5, 25, 50')
S[31]['notes']+=' Hàng K=5 trên slide này vẫn là seed 0, không thay bằng mean ba seed. Chưa chạy K=25/50 cho seed 1/2, nên không có SD nhiều seed cho khảo sát này.'
update(34,title='Độ nhất quán và giới hạn của ba seed',message='Cải thiện cùng dấu là bằng chứng mô tả, chưa phải kiểm định thống kê',
       notes='Dữ liệu ba seed hỗ trợ ba nhận định: DS-AL có A_K và A-bar cao hơn ACIL trong từng seed; PLC cải thiện cả hai chỉ số so DAC không PLC trong từng seed; DAC đơn lẻ chưa cải thiện ổn định A_K so ACIL. SD của A_K cho ACIL/DAC/DS-AL lần lượt '+', '.join(f(A[m]['last_accuracy']['sd']) for m in core)+' pp, phản ánh mức biến động quan sát giữa các seed. Chưa có kiểm định phù hợp, và n=3 nhỏ, nên không dùng tính nhất quán dấu hoặc SD nhỏ để khẳng định ý nghĩa thống kê hoặc tổng quát. Seed 0 resume CUDA→CPU tại epoch 19 còn seed 1/2 CPU xuyên suốt; không coi biến thiên hoàn toàn do random seed. Class order, initialization, projection và chi tiết training khác paper có thể liên quan gap, nhưng chưa được can thiệp riêng. K/buffer chỉ seed 0. Synthetic comparison với mã tác giả chứng minh phạm vi tương đương/khác biệt cụ thể, không xác lập nguyên nhân gap CIFAR.',methods=core)
update(35,title='Kết luận trên ba seed CIFAR-100',message='Đã đo lợi ích ghép cặp và giữ rõ phạm vi của bằng chứng',
       notes='Nhóm tái dựng độc lập main ridge, DAC và PLC; đối chiếu toán học và mã tham chiếu riêng; hoàn thành ACIL, DAC không PLC, DS-AL trên ba seed CIFAR thật. DS-AL đạt mean A_K '+ms('dsal-k5','last_accuracy')+'%, mean A-bar '+ms('dsal-k5','average_accuracy')+'%. DS-AL−ACIL tăng mean A_K +0,4033 pp và A-bar +0,1257 pp; PLC−DAC không PLC tăng +0,4700 pp và +0,3100 pp tương ứng. Hai dấu cải thiện nhất quán 3/3 seed, nhưng chưa có kết luận ý nghĩa thống kê. DS-AL còn thấp hơn mean paper 1,4867 pp ở A_K và 1,1324 pp ở A-bar. Khảo sát K/buffer vẫn chỉ seed 0. Chưa tái hiện ImageNet; ablation được chuyển dataset và cần diễn giải trong CIFAR. SD ba seed là thống kê mô tả, có hạn chế backend của seed 0, không phải bảo đảm tổng quát.',methods=core)
update(39,title='Phụ lục: từng seed và provenance',message='Mỗi ô ghi Ā và A_K (%), giữ riêng dữ liệu của từng seed',
       notes='Mỗi ô bảng ghi A-bar và A_K (%) của một seed, không phải accuracy từng pha. Các số được tính từ đúng sáu pha và đối chiếu summary/history W&B. Full dataset revision: aadb3af77e9048adbea6b47c21a81e47dd092ae5. Ba checkpoint SHA-256: '+'; '.join(f'seed {r["seed"]}: {r["summary"]["checkpoint_sha256"]}' for r in base)+'. Class order dùng RandomState(seed); 12 lớp đầu theo từng seed: '+'; '.join(f's{seed}: '+','.join(map(str,next(r for r in v['runs'] if r['seed']==seed and r['method']=='dsal-k5')['config']['feature_identity']['class_order'][:12])) for seed in [0,1,2])+'. Python 3.11.8, torch 2.5.1+cpu cho các lượt CPU, stats/float64, analytic batch 512; W&B 0.23.1 offline và 0.31.0 sync. Source, config và feature caches có hash, trọng số backbone độc lập giữa seed và projection ghép cặp đã được kiểm tra. Hai seed bổ sung dùng 6,2279 giờ cho backbone/features và analytic, không gồm downtime/sync/diagnostics. Peak RSS lấy mẫu 1,576 GiB, private memory 2,160 GiB, lấy mẫu mỗi 10 giây nên có thể bỏ lỡ đỉnh ngắn. Chi tiết đầy đủ ở assets/three_seeds_verified.json và experiments/multiseed/20261119/.',methods=core)
update(40,message='Tách bảo đảm đại số, khảo sát seed 0 và cải thiện ghép cặp ba seed',
       notes='Main head bằng nghiệm joint ridge là bảo đảm đại số khi feature, projection, activation, gamma cố định, padding đúng và cập nhật đủ dữ liệu. Không suy ra CNN không quên hoặc toàn compensation bất biến. Accuracy gần nhau khi thay K chỉ được quan sát trên seed 0; không là đẳng thức trọng số hoặc kết quả nhiều seed. Trong CIFAR K=5, PLC tăng A_K mean +0,4700 pp so DAC không PLC và DS-AL tăng +0,4033 pp so ACIL; các chênh dương ở 3/3 seed. Đây là bằng chứng thực nghiệm mô tả, không khẳng định ý nghĩa thống kê. Seed 0 có đoạn resume đổi backend; K/buffer chỉ có một seed. Các seed của synthetic mechanism là bộ dữ liệu tổng hợp riêng và không tính vào ba seed CIFAR. E2 chuyển dataset từ ImageNet-Full, không suy rộng nguyên Table 2. Giữ các phạm vi này giúp tránh biến một quan sát accuracy thành bảo đảm không được dữ liệu hoặc định lý hỗ trợ.',methods=['dac-no-plc-k5','dsal-k5'])

